(function(root){'use strict';
const D={"version":"CH2-DIALOGUE-1","sceneCount":90,"lineCount":1255,"changes":{"visitor_songfeng_route":{"（我在自己的纸上分两栏抄，原图一笔不动。）":"（渡口旁边记上日子……这几处问号也照着抄，省得下回忘了问。）","先看同行的人和带的东西，再问路是何时查过的。拿不准就问，别只靠脚下有力气。":"独自走，和背着两包药走，是两回事。这坡我前日才看过，眼下还滑；你若赶时辰，宁可多走两里。","这些我还不会判断。先把要问什么记下来，回练场再请教师父。":"我平地上还会绊脚，这坡还是跟着您走。绕路的地方，我先记下来。"},"visitor_whiteheron_records":{"我想多看看你们怎样安排复诊。这里的日常先继续做，之后怎么学，我还要想清楚。":"你们遇到治不好的病，是去请哪位先生？下回来，我想跟着看看。","下回来白鹇谷，我带你去看看。真想跟着学，咱们再慢慢谈。":"好。下月有位老先生坐诊，你若来，我替你留个位子。带上你想问的那几页。"},"visitor_zhaochuan_greeting":{"自然。先听场上怎样开始、怎样停，别越过场边的线。报名也有要求，到了再问明白。":"先站在绳外看。叫停就得收手——这一条，参赛的和看热闹的都得记着。你若想报名，到了找门口执事。","先练了拳脚的起手和收势，还在纠正站位。":"师父教了《守拙拳法》。出拳还成，收回来的时候，总要多挪一步。","学过入门剑式，距离与收势还在练。":"学的是《试锋剑法》，试锋探路这一招。剑尖老停不准，师父还在给我改。"},"gy_noodles":{"你入门那年才十四，吃了一个就吐了。":"你入门那年才十一，吃了一个就吐了。","我也十七！可我比你早入门三年——往后你得叫我师兄。":"我十四！可我十一岁就入门了，比你早三年——往后你得叫我师兄。","……同岁也算？":"你比我小三岁，也得叫师兄？"},"gy_prelude_xinfa":{"根基扎住了，可以开始学心法了。归云谷的功夫，先练气，再练招。":"腿站得住了，今天教你调息。这一篇叫《吐故纳新篇》，先把气喘匀。","坐下。不必盘得好看，腰背挺直，肩放松。吸气的时候，想着气沉到脐下三寸；吐气的时候，想着它像云一样散开。":"坐下，肩别耸着。吸气不要抢，吐气也别急。你先跟着我做三回。","……像云一样？":"这就是谷里的心法？","归云心法。云散了还会回来，气也是。练到后来，你就知道为什么叫这个名字。":"这是入门调息，不是本门的上乘心法。先练好它；往后受得住了，我再教你《出岫心经》。","什么也不必感觉。先数呼吸，数到一百，不乱，就算入门。":"先别找什么气感。数自己的呼吸，数乱了，就从头来。","数到第三十几你就知道了。":"你先数过三十，再说简单。","醒了？往后每天早晚各一次，不许间断。":"醒了？困了就歇，别硬撑。明早再来，我看你能不能数到四十。","（归云心法……来到这里以后，学会的第一门功夫。居然是睡过去的。）":"（《吐故纳新篇》……名字记住了。数到哪儿睡着的，倒是一点也想不起来。）"},"gy_prelude_hair":{"根基打完了。往后三年，学武、行医、交朋友、下山见世面——一样一样来。":"这两个月，总算没把你练瘦。明早想学什么，自己去找你师父；今晚先把饭吃了。"},"gy_m03":{"先托人带个话。等见了面，再问他们当年见过什么。":"我再托人问一封。若约得上，进城时就去见见。","好。这封信我先收好。师父，多谢您。":"我先收着。周先生，多谢您。"},"gy_m04":{"药包我再数一遍，临走就能装车。家里的旧物，我另收着。":"药包还差最后一遍清点。陆大哥，装车前叫我。"},"gy_m05":{"数目齐了。我想问的事写在另一张纸上，自己拿着。":"药签和包数对上了。那封问消息的信，我放在内袋，别让雨打湿。","这回要带给谁，我记着。":"三包给王大夫，余下的送到安置院。我没记反吧？","绕这条路。东西分成三份，萧白只管平地上搬，顺手清点数目。":"走左边。来，这包轻些，你背着。上坡的那两包我拿。","路我看过了。平的这一段交给你们，跟着我绕过去。":"路我看过了。前面那几块石头能落脚。跟着我，一步一步来。","自己发现就好。余下的我们一起走。":"记着这个地方。包给我，你们跟在后头，别抢着过。"},"gy_m06":{"是陆大哥先看过路，我在他旁边走了一小段。退步还不稳。":"陆大哥在旁边接着我，才走过那段坡。最后一步差点又迈大了。","我们分了包绕路，我帮忙托和清点。坡上的走法，我还得学。":"我们绕了路。我搬了些包，可一上坡还是得陆大哥带着。","我拿不准，就请他安排。要先问什么，我现在有一点头绪了。":"我不敢上去，就叫住了陆大哥。他带着走一遍，我才知道踩哪儿。"},"gy_m07":{"我想看看自己练过的东西，遇到别人时用得怎么样。":"我也去。想看看别人怎么出剑、出拳……光看小豆，我都快猜到下一招了。","我家的东西不当贺礼。":"周先生，贺礼里没有我家的旧物吧？","自然，那是你家里的东西。赴宴的礼，谷里来备。":"没有。你师母已备下了，明日你去厨房看，一大包，都是她挑的。"},"gy_m08":{"我给周婶留了捎信的地址。陈伯的情况，还是照原来那条路问。":"周婶知道我们要进城。下封信她会捎到客店，不用来回找。","日用的都装在外袋了。家里的东西我自己收着，别和贺礼弄混。":"我把药和干粮放在外袋。家里的册子在箱底，那一袋别替我拿。","这回我先吃，碗凉了，路也不会变短。":"说着说着，菜都凉了。你给我递一下那盘笋。"},"gy_m09":{"好。这回是我们自己要来。":"好。客店见。别看起比武，就把时辰忘了。","走吧。城门口先把来意说清，别的事，进城再慢慢打听。":"走。先进城安顿，今日不赶着办事。","好。这回是我们自己要来——有你在旁边，我问话也不慌。":"好。若问到了消息，我先告诉你。……你也别走太远。"},"gy_z01":{"说说你脚下的感觉。我指给你看，回头还是得自己练。":"把脚放回刚才那儿。你看，腰先倒过去了，脚当然接不住。","下次先拆开这一步。今天不加快，你先认清自己站在哪里。":"手先别动，只退这半步。脚落稳了，腰再跟上。","还是这里。我先问明白，再把次数加上去。":"还是这儿。师父，再看我退一次？","今夜不必再练。吃饭时也不用反复想着怎么赢第三回。":"今日到这儿。回去吃饭，别端着碗还在底下挪脚。"},"gy_y02":{"你知道就别说。我现在只想把今晚该交代的写清。":"那就别哄我。替我拿张新纸吧，这一张快改穿了。","嗯，这条只回他消息收到了。怎么诊治，还是得问那边的大夫。":"嗯，先告诉他药到了。病人的那几句，我问清楚再补。","你给我留半碗就好。我今天不再另整理一批。":"留半碗。写完这封，我就来。"},"gy_l02":{"你那份自己写，旁人的签名留给旁人。":"来，你试着写。最后这一格先空着，得等王家收了东西才填。","那这项我写“待收件方确认”。":"那就写“还没收到回话”。这样王家也看得懂。","嗯。没回话就先空着，总比替人答应强。":"对。回信来了，再把日子添上。","问完也不必都找我。有合适的人就请他，人家不接也留条路。":"先问哪天用。急的托快船，不急的等我这趟回来。别一股脑都堆在门口。"},"gy_y03":{"我也该有一项，不只是别人缺什么。":"方子抄了半页，就有人喊我。等回来，又把想问的忘了。","你先写。我那项等你写完再说。":"那你先把这一行写完。我替你看着外头，有人找，我去应一声。","想看看外头的大夫遇上难症，怎样找人商量。忙不过来时，又怎样请人接手。":"想去白鹇谷看一回诊。碰上我治不好的病，他们是怎么下手的？","对。听过、看过，我再想往后怎么学。":"对。去看过再说。不能只凭一封信，就认定那里适合我。","这页我收好。家里的东西，也还是我自己留着。":"这页得收好，别又夹进待晒药材那一堆里。"},"gy_z03":{"报我的名字，是说从哪里学。不是说你已经都会。":"他们问你会什么，就说会什么。我的名声，不用你一场打回来。","先看是什么项目，做不做由你说。规矩要守，夸下的话也要自己担。":"问清比什么。能试就试，不会就说不会。我又没叫你争第一。","也可以。别替旁人签收，不懂的先问经手人。":"行。搬不动就两个人抬，清点时别只听别人喊数。","师门的名字不能替我把数量点对。":"这个我会。……至少不会把三包数成两包。","我就说学过基础拳脚，收势还没练好。练到第几重，也照实说。":"那就说练的是《守拙拳法》。出拳不难，就是回收还慢。","我就说学过试锋剑法，距离和收势还不熟。用的是谷里的练习剑，也还没自己的佩剑。":"那就说练的是《试锋剑法》。手上拿得稳了，剑尖还停不太准。"},"gy_fang_back":{"嗯。说实话的人，练得最快。":"我当年也抖。明早一起来，我看看你最后那半炷香。","……腿，稳了？":"……大师兄，我腿还在抖。您都看见了。"},"gy_fist_or_sword":{"萧白，你自己说。往后一个月，先跟谁练？":"萧白，你选。钟师叔陪你练拳，红缨陪你试剑；《守拙拳法》《试锋剑法》，我来亲授。","我连站都还没站稳。先跟二师叔练根基吧。":"我先学《守拙拳法》，跟二师叔把脚下练稳。","我想先看看……真的江湖上是怎么打的。":"我想先学《试锋剑法》。小师叔，您陪我试试？","那就这么定了。":"陪练就这样定。正课还得来找我，一门一门学，别在饭桌上就算学会了。"},"gy_goose_steps":{"我那是十四岁！":"我那时候才十一岁！"},"gy_brother_hurt":{"大师兄也是人，也会受伤。":"平日都是你喊我早起。今天换我守着，你睡吧。","你被抬回来的时候，第一句话是“把东西收好”。我觉得，这就够格了。":"你伤成那样还惦记那封信，师父都看见了。……先把伤养好，别今晚就想这些。"},"gy_go_in_stead":{"好。这也是担当。":"那你帮叶蘅照看方迟。有事先找钟师叔。","问明白了。不是冲着归云谷来的。":"人找到了，信也对上了。山下那笔药钱还没结，我已约他们下回当面说。"},"gy_mid_autumn":{"……谷里太好了。人一习惯了好，就会怕失去。我怕哪天回来，这个家散了，所以干脆少回来。":"……有时候在外头拖着不回来，嘴上说是有事。其实到了山口，又怕师兄问起这几年。"},"gy_dou_runaway":{"真的。所以更不能现在就走——好东西，要先磨锋利了。等你出师那年，我亲自带你下山。":"真的。可你才跑三里，馒头就掉了两个。出门哪能这么毛躁？包扎好，等出师那年，我带你走。"},"gy_year_exam":{"记着这份怕。会怕，才知道为什么要练。——考校，过了。":"那就继续练。方迟伤着的时候，你守了一夜；不是只能站着看。——这一年，算过了。"},"gy_new_year":{"新年好。——归云谷的第一年，过完了。":"新年好！锅里还有面，谁饿了自己盛，今夜不熄火。"},"gy_yin_past":{"这事我没跟第二个人说过。":"师父罚我跪的那三天，我这些年没再跟人提过。"},"gs_old_manual":{"拳谱是死的。先把站桩站好。":"先放回去。明早练《守拙拳法》，我给你看这页为什么少了一行。"},"gs_rations":{"记着，干粮先吃硬的，软的留到最后。":"分两包装。给同伴的那份先留好，别半路一饿，全吃了。"},"gs_fireflies":{"看一会儿就放了吧，它离了水活不久。":"手松一点，别压了翅膀。看够了就放回草边。","明天还来！":"……叶蘅姐姐，你不想说就不说。我们坐这儿看一会儿吧。"},"gs_herb_hunt":{"……这样最好。有毒的长得都好看。":"……好。先别碰那一丛，它不是黄精。你替我把篓子放过来。","够了。剩下的留给山。":"这篓够用了。剩下的别挖，明年再来。"},"gs_calligraphy":{"字是人的样子。慢慢写。":"手腕松些。你把这笔压得太重，纸快戳穿了。"},"gs_bandage":{"被抬回来那次，我躺着看叶姑娘包了一个月。看会了。":"下山前师父教过。回来又挨了叶姑娘一顿数落——我那回扎得太紧。","学会了，就别有用上的那天。":"拿块布再练两遍。真要用时，可没人站旁边替你收拾。"},"gs_snow_roof":{"嗯。今晚这一口气，比你一个月练的都匀。":"嗯。这一回匀了。记住刚才肩上松下来的感觉，明早也这样练。"},"gn_lamp":{"糊了的也给我。糊成什么样，本身也是一条记录。":"糊了的也给我，页角还在。拿去和底稿对对，说不定还能补。"},"gn_words":{"我送你到溪边。……“后来呢”这三个字，你往后要是还想问，来问我。我也想知道。":"我送你到溪边。……刚才那三百个人……我九岁时也问过。你往后翻到他们的消息，记得喊我。"},"gn_terraces":{"纸会夹错书，人不会。":"还记得田头那两户吧？我陪你去，省得又漏问一家的。"},"gn_ye_ink":{"来。你娘的字很好认，一笔是一笔。……写这种字的人，开方子也不会含糊。":"来。你娘的字，我认得几处了。……往后再有洇开的，拿来一块儿看。"},"gn_eyes":{"告诉他吧。他教你有据才录，没教你瞒着。":"告诉他吧。你怕他难过，可他天天坐在你旁边，总不能一直不说。","十一页是心思，一整册是东西。他是读书人，看东西。":"就把这十一页也带给他看。你想写什么，让他自己读，比我替你讲明白。"}},"activities":{"B03":{"task":"脚跟落稳，膝不锁死。请钟拙看一次，再慢练收势。","feedback":"二师叔点了点脚边：这一次，你没往前扑。"},"B02":{"task":"退半步、转身、再站住。先慢后快，不抢着跨大步。","feedback":"退步后站住了，转身时没有绊脚。"},"B01":{"task":"按《吐故纳新篇》调息。数乱了就重来，困了不硬撑。","feedback":"肩放松了。最后一轮呼吸，比开头匀。"},"B04":{"task":"活动肩背，做一轮转身与落脚。","feedback":"肩背松了些，手脚终于接上了半拍。"},"B05":{"task":"闭眼听小师叔的脚步。先分出竹叶声，再说她在哪边。","feedback":"第三次转身时，你正对着她。"},"B06":{"task":"观察师父起手时的肩与脚，说出哪一边重心先动。","feedback":"手还没动，你先看见他脚跟提了起来。"},"K01":{"task":"学习并练习《试锋剑法》的试锋探路，先练剑尖停在哪里。","feedback":"剑尖停准了，收剑时也没向前扑。"},"K02":{"task":"学习并练习《守拙拳法》的守拙立桩，出拳后仍能站住。","feedback":"拳收回腰间，脚下还是稳的。"},"P01":{"task":"翻晒药材、添水，收一份已经认过的普通药材。","feedback":"晾架翻好了，辨过的一份药材也收进了篓子。"},"P02":{"task":"用一份食材做干粮，晾凉后分包装好。","feedback":"干粮装好了。出门前再数一数，给同伴的别漏了。"},"P03":{"task":"用一份布料做日用布包，试试接缝和绑带。","feedback":"装上东西提了一回，接缝没有松。"},"A01":{"task":"拿练习中卡住的一步，请周砚示范。","feedback":"那半步拆开一看，原来是腰比脚走得早。"},"A02":{"task":"按时间抄医案，把看到的症状与大夫的判断分开记。","feedback":"日期、症状与处置抄齐了，叶蘅划去一处写反的。"},"A03":{"task":"对照药签认普通样品，看叶背、闻气味，再问叶蘅。","feedback":"认出了今日几味样品。叶蘅让你明日来帮着翻晒。"},"A04":{"task":"请陆衡检查包带，问雨后山路怎么落脚。","feedback":"松掉的包结收紧了，坡上该停在哪儿也记下了。"},"A05":{"task":"跟着做一顿家常饭，认好厨房器具。","feedback":"锅底没有再糊。这回的干粮，可以自己动手做了。"},"A06":{"task":"拿普通布头练缝补，把断开的接缝补牢。","feedback":"绑带提得住了，下一回可以试着缝整个布包。"},"D01":{"task":"添满廊下水缸。两桶太重就少装些，走稳再添。","feedback":"水缸添满了，回去时空桶也没磕膝盖。"},"D02":{"task":"扫落叶，把练场器具搬回原处。","feedback":"落叶扫净，木棍一根根靠好了。"},"D03":{"task":"把晾架药签逐一配回材料，模糊的留给叶蘅看。","feedback":"缺字的药签另放一边，没再混进已经配好的那筐。"},"D04":{"task":"磨好墨，收整用过的纸笔。","feedback":"墨磨匀了，书案也腾出一角。"},"D05":{"task":"换掉竹篓裂开的篾，收好毛边。","feedback":"拿重物试了一回，篓底没再漏。"},"C01":{"task":"选一位已经认识、能收到信的人，写近况。","feedback":"信交给了捎信人，下期留意回话。"},"C02":{"task":"选一位已相识的人，送一份自己的干粮、药材或布包。","feedback":"物品交给捎物人，下期留意回话。"},"W01":{"task":"就修习里的一个困难认真长谈，本次只展开这一段。","feedback":"师父听完你的难处。谈话留下下一次练习的方向。"},"W02":{"task":"参加已知的整理邀约，听她说当前的生活安排。","feedback":"你们把不确定的内容留待核实。下一次帮忙，先问清许可；家传旧物没有取用。"},"W03":{"task":"听近况并记录普通需要，不自动领取全部委托。","feedback":"你们记下实际需求和未确定的事项。读信没有让陈伯痊愈，也不算已经完成实地回访。"},"W04":{"task":"观察已知近路，把受教的步法用在不同地面。","feedback":"（这条近路走熟了。溪边那几块石头沾水就滑，下回落脚得避开。）"},"W05":{"feedback":"陆衡确认了本次委托的范围，仍要履行其他护运工作。你不再把顺路当作没有代价。"},"W06":{"feedback":"你和师父按实际护送经历确定下一次练习方向；没有凭空学会进阶武学。"},"W07":{"feedback":"二人分别写下出行目的。遗物仍由叶蘅决定是否携带，没有提前决定她的职业路线。"},"QH01":{"task":"翻到陆大哥画的那一页，照着复习握持、回收和护身。","feedback":"按教过的次序练了一遍，棍头收回时没再碰到衣角。"}},"correspondence":[{"id":"zhou-letter","name":"周砚","field":"letter","sourceText":"周砚回信：你写的不稳之处，我看过了。下回练习先把它说清，不必只报做得好的。","text":"周砚回信：你说退步时右脚总慢半拍。下回把剑先搁下，空手退给我看。别的功课照旧。"},{"id":"zhou-repeat","name":"周砚","field":"repeat","sourceText":"周砚：上回留下的还用得上。练场的事慢慢做，不必次次添东西。","text":"周砚：上回那个还好好的。你师母若见我又收一份，该问我是不是把东西练坏了。"},{"id":"zhou-gift-food","name":"周砚","field":"gifts","gift":"food","sourceText":"周砚：放在练场边，练完再吃。别拿空着肚子多站一会儿当勤勉。","text":"周砚：放在边上吧，练完一起吃。你先别嚼，嘴里塞着东西还怎么调息？"},{"id":"zhou-gift-herb","name":"周砚","field":"gifts","gift":"herb","sourceText":"周砚：药性我不替叶蘅定，你将来源写清，交到药圃去。","text":"周砚：这个得问叶蘅。我若收进练场，明日你怕是要拿药草擦剑了。"},{"id":"zhou-gift-pouch","name":"周砚","field":"gifts","gift":"pouch","sourceText":"周砚：正缺个装木楔的小包。绑带磨损时再补，别硬撑着用。","text":"周砚：正好。木楔总滚在箱底，找一块得翻半天。这个我留下。"},{"id":"zhou-returnText","name":"周砚","field":"returnText","sourceText":"随信附普通布料一份，补一补磨损的绑带。","text":"随信附普通布料一份，补一补磨损的绑带。"},{"id":"ye-letter","name":"叶蘅","field":"letter","sourceText":"叶蘅回信：药圃今日又留了一格空签，是还没问清，不是忘了写。你的近况我看了。练完也记得吃饭，别总等我提醒。","text":"叶蘅回信：昨夜抄方子抄得迟，今早险些认错自己的字。你信里说的事，我记着了。回来帮我看一眼那株新长的紫苏？"},{"id":"ye-repeat","name":"叶蘅","field":"repeat","sourceText":"叶蘅：先前送来的还没整理完，我记得。下次先问缺什么，省得你又跑一趟。","text":"叶蘅：先前送来的还没整理完，我记得。下次先问缺什么，省得你又跑一趟。"},{"id":"ye-gift-food","name":"叶蘅","field":"gifts","gift":"food","sourceText":"叶蘅：干粮收好了。你自己那份呢？别把午饭也塞给我。","text":"叶蘅：干粮收好了。你自己那份呢？别把午饭也塞给我。"},{"id":"ye-gift-herb","name":"叶蘅","field":"gifts","gift":"herb","sourceText":"叶蘅：来源写得明白，我才好分拣。这些只是普通药材，不与家里的旧物混放。","text":"叶蘅：从哪儿采的？……山阴那一片？好，我记上。药篓放这儿，你歇一会儿。"},{"id":"ye-gift-pouch","name":"叶蘅","field":"gifts","gift":"pouch","sourceText":"叶蘅：这个正好装空白药签。待问的和确定的分开，省得一忙就混在一起。","text":"叶蘅：空白药签总散得到处都是。有了这个，我可不能再赖桌子小了。"},{"id":"ye-returnText","name":"叶蘅","field":"returnText","sourceText":"随信另附一份已分拣的普通药材，给你辨药时用，不是家传旧物。","text":"叶蘅另包了一份药圃分好的普通药材，药名写在纸上：“回来考你，别把签丢了。”"},{"id":"lu-letter","name":"陆衡","field":"letter","sourceText":"陆衡回信：你说的近况记下了。我这段路按原定归期走，若要托带东西，先写清终点和数量，别替我答应旁人。","text":"陆衡回信：过渡口时赶上了雨，晚走半日。东西都到了，你不必再惦记。下月回来，替我留一碗热汤就行。"},{"id":"lu-repeat","name":"陆衡","field":"repeat","sourceText":"陆衡：上回那份还在行囊里。这段路够用了，不必再为我多备。","text":"陆衡：上回那份还在行囊里。这段路够用了，不必再为我多备。"},{"id":"lu-gift-food","name":"陆衡","field":"gifts","gift":"food","sourceText":"陆衡：下一段路赶早，这份干粮用得上。回谷自己做顿热的，也别只靠干粮。","text":"陆衡：下一段路赶早，这份干粮用得上。回谷自己做顿热的，也别只靠干粮。"},{"id":"lu-gift-herb","name":"陆衡","field":"gifts","gift":"herb","sourceText":"陆衡：药材另包了，不和路单混放。我只捎到药摊，如何用还得请医者看。","text":"陆衡：我另包着，过集市时捎给王大夫。对了，这包上写的是你的名字吧？"},{"id":"lu-gift-pouch","name":"陆衡","field":"gifts","gift":"pouch","sourceText":"陆衡：路单总被磨出毛边，这包正合适。终点与归期仍照原约，不能因为收了东西就替你多揽一趟。","text":"陆衡：好东西。上回路单在包底磨破了，找个渡口还得把半张纸拼起来。"},{"id":"lu-returnText","name":"陆衡","field":"returnText","sourceText":"途经集市买了点普通食材，捎一份给你们做热饭。","text":"途经集市买了点普通食材，捎一份给你们做热饭。"},{"id":"neighbor-letter","name":"乡邻","field":"letter","sourceText":"陈伯托人带信：腿还在慢慢养，周婶已把安置处收拾妥当。你们安心学本事，不必把所有人的活都揽到自己身上。","text":"陈伯托人带信：拄杖能走到门口了，周婶还不许我出院子。你们的信她念了两遍。谷里凉，添件衣裳。"},{"id":"neighbor-repeat","name":"乡邻","field":"repeat","sourceText":"周婶托话：上回那份还没用完，别又把自己的东西搬来。下回捎个近况就好。","text":"周婶托话：上回那份还没用完，别又把自己的东西搬来。下回捎个近况就好。"},{"id":"neighbor-gift-food","name":"乡邻","field":"gifts","gift":"food","sourceText":"陈伯托人带信：这份干粮留在床边，夜里饿了不用叫人起身。腿还在养着，你们别为我赶路。","text":"陈伯托人带信：夜里饿了，伸手就拿得到。你们学本事去，等我腿好了，回头请你们吃面。"},{"id":"neighbor-gift-herb","name":"乡邻","field":"gifts","gift":"herb","sourceText":"陈伯托话：药材收着了，会先请医者辨认。来意我知道，养伤的事还是照医嘱办。","text":"陈伯托话：收到了，搁在大夫开的药旁边。周婶说，等他明日来一起看。你们也照顾好自己。"},{"id":"neighbor-gift-pouch","name":"乡邻","field":"gifts","gift":"pouch","sourceText":"周婶写信：散着的针线终于有处放。收拾好行李，找东西也不用来回翻了。","text":"周婶写信：散着的针线终于有处放。收拾好行李，找东西也不用来回翻了。"},{"id":"neighbor-returnText","name":"乡邻","field":"returnText","sourceText":"修补后还有一份普通布料余料，一并捎给你，不是要你再添一包。","text":"周婶捎来一份补衣剩下的普通布料：“这块结实，包东西也使得。”"},{"id":"shimu-letter","name":"江采薇","field":"letter","sourceText":"师母回信：信写得工整，比你师父强。练功别空着肚子，厨房留了饭，自己去热。","text":"师母回信：信写得工整，比你师父强。练功别空着肚子，厨房留了饭，自己去热。"},{"id":"shimu-repeat","name":"江采薇","field":"repeat","sourceText":"师母：上回的还没用完呢。东西别老往我这儿搬，人回来吃饭就行。","text":"师母：上回的还没用完呢。东西别老往我这儿搬，人回来吃饭就行。"},{"id":"shimu-gift-food","name":"江采薇","field":"gifts","gift":"food","sourceText":"师母：干粮自己做的？面揉得还欠点火候。收下了，明儿我教你。","text":"师母：干粮自己做的？面揉得还欠点火候。收下了，明儿我教你。"},{"id":"shimu-gift-herb","name":"江采薇","field":"gifts","gift":"herb","sourceText":"师母：正好，库里的伤药快见底了。来源写清楚了，我分好了收起来，谁受伤谁来领。","text":"师母：正好，库里的伤药快见底了。来源写清楚了，我分好了收起来，谁受伤谁来领。"},{"id":"shimu-gift-pouch","name":"江采薇","field":"gifts","gift":"pouch","sourceText":"师母：针脚还行。我拿来装绣针，往后谁偷懒，我就从这里摸针。","text":"师母：针脚还行。我拿来装绣针，往后谁偷懒，我就从这里摸针。"},{"id":"shimu-returnText","name":"江采薇","field":"returnText","sourceText":"随信附一份普通食材——别省着，长身体呢。","text":"随信附一份普通食材——别省着，长身体呢。"},{"id":"pei-letter","name":"裴知古","field":"letter","sourceText":"裴知古回信：你的信我看了三遍。第一遍看内容，后两遍看你那些缺笔画的字——有几个我已经猜出是什么了。","text":"裴知古回信：你的信我看了三遍。第一遍看内容，后两遍看你那些缺笔画的字——有几个我已经猜出是什么了。"},{"id":"pei-repeat","name":"裴知古","field":"repeat","sourceText":"裴知古：这个上回给过了。……我没忘，我记在册子里了。","text":"裴知古：这个上回给过了。……我没忘，我记在册子里了。"},{"id":"pei-gift-food","name":"裴知古","field":"gifts","gift":"food","sourceText":"裴知古：谢谢。我先放着——上回放着的那份呢？啊，在书箱上，硬了。这回我现在就吃。","text":"裴知古：谢谢。我先放着——上回放着的那份呢？啊，在书箱上，硬了。这回我现在就吃。"},{"id":"pei-gift-herb","name":"裴知古","field":"gifts","gift":"herb","sourceText":"裴知古：这是防蠹的那一种吗？夹在书页里正好。不是？那我问问叶姑娘怎么用。","text":"裴知古：这是防蠹的那一种吗？夹在书页里正好。不是？那我问问叶姑娘怎么用。"},{"id":"pei-gift-pouch","name":"裴知古","field":"gifts","gift":"pouch","sourceText":"裴知古：布囊……我正缺一个装书签的。原来那个被我当书签夹进书里了。","text":"裴知古：布囊……我正缺一个装书签的。原来那个被我当书签夹进书里了。"},{"id":"pei-returnText","name":"裴知古","field":"returnText","sourceText":"随信夹了一枚她自己裁的书签。","text":"裴知古随信夹来一小块普通布料：“包书角用的，裁剩这块，给你。”"},{"id":"yin-letter","name":"殷红缨","field":"letter","sourceText":"小师叔回信：字太规矩，看得我犯困。下回写点好玩的——比如你今天又被将军啄了几口。","text":"小师叔回信：字太规矩，看得我犯困。下回写点好玩的——比如你今天又被将军啄了几口。"},{"id":"yin-repeat","name":"殷红缨","field":"repeat","sourceText":"小师叔：又是这个？我又不是将军，不用天天喂。……不过收下了。","text":"小师叔：又是这个？我又不是将军，不用天天喂。……不过收下了。"},{"id":"yin-gift-food","name":"殷红缨","field":"gifts","gift":"food","sourceText":"小师叔：下酒正好。你自己做的？咸了。……下回还要。","text":"小师叔：下酒正好。你自己做的？咸了。……下回还要。"},{"id":"yin-gift-herb","name":"殷红缨","field":"gifts","gift":"herb","sourceText":"小师叔：给我药材做什么，我又不会熬。——行吧，放你师母那儿，算我的份。","text":"小师叔：给我药材做什么，我又不会熬。——行吧，放你师母那儿，算我的份。"},{"id":"yin-gift-pouch","name":"殷红缨","field":"gifts","gift":"pouch","sourceText":"小师叔：布包？拿来装酒葫芦的塞子倒是合适。针脚歪了，像你的剑。","text":"小师叔：布包？拿来装酒葫芦的塞子倒是合适。针脚歪了，像你的剑。"},{"id":"yin-returnText","name":"殷红缨","field":"returnText","sourceText":"随信塞来一块外头带回的普通布料：“给你补练衣，别穿得破破烂烂丢我的人。”","text":"随信塞来一块外头带回的普通布料：“给你补练衣，别穿得破破烂烂丢我的人。”"},{"id":"zhong-letter","name":"钟拙","field":"letter","sourceText":"二师叔回信：字写这么小，我得眯着眼看！下回写大点。木人桩又加了一条腿，回来试试。","text":"二师叔回信：字写这么小，我得眯着眼看！下回写大点。木人桩又加了一条腿，回来试试。"},{"id":"zhong-repeat","name":"钟拙","field":"repeat","sourceText":"二师叔：又送？上回那份我还没吃完——不对，吃完了。放这儿吧。","text":"二师叔：又送？上回那份我还没吃完——不对，吃完了。放这儿吧。"},{"id":"zhong-gift-food","name":"钟拙","field":"gifts","gift":"food","sourceText":"二师叔：好！干活就得吃饱。下回多做两个，你小豆师兄也惦记着。","text":"二师叔：好！干活就得吃饱。下回多做两个，你小豆师兄也惦记着。"},{"id":"zhong-gift-herb","name":"钟拙","field":"gifts","gift":"herb","sourceText":"二师叔：药材？我又不生病。……行，拿去给叶姑娘，就说是我送的。","text":"二师叔：药材？我又不生病。……行，拿去给叶姑娘，就说是我送的。"},{"id":"zhong-gift-pouch","name":"钟拙","field":"gifts","gift":"pouch","sourceText":"二师叔：这包结实！正好装凿子刨刀，比我那个破的强多了。","text":"二师叔：这包结实！正好装凿子刨刀，比我那个破的强多了。"},{"id":"zhong-returnText","name":"钟拙","field":"returnText","sourceText":"随信附一块包木器剩下的普通布料：“缠棍柄用，缠紧了手不打滑。”","text":"随信附一块包木器剩下的普通布料：“缠棍柄用，缠紧了手不打滑。”"},{"id":"fang-letter","name":"方迟","field":"letter","sourceText":"大师兄回信：谷里的事有你和小豆，我放心。功课别落下，回来我要看你站桩。","text":"大师兄回信：谷里的事有你和小豆，我放心。功课别落下，回来我要看你站桩。"},{"id":"fang-repeat","name":"方迟","field":"repeat","sourceText":"大师兄：上回的还够用。你自己留着，出门比我更用得上。","text":"大师兄：上回的还够用。你自己留着，出门比我更用得上。"},{"id":"fang-gift-food","name":"方迟","field":"gifts","gift":"food","sourceText":"大师兄：路上正缺这个。你做的？比我做的强。","text":"大师兄：路上正缺这个。你做的？比我做的强。"},{"id":"fang-gift-herb","name":"方迟","field":"gifts","gift":"herb","sourceText":"大师兄：这几味正好换药用。来源写清了，我按叶姑娘的法子收好。","text":"大师兄：这几味我用得上。你替我谢过叶姑娘，药名她写得清楚。"},{"id":"fang-gift-pouch","name":"方迟","field":"gifts","gift":"pouch","sourceText":"大师兄：装信正合适。上回就是信袋太薄，差点湿了。","text":"大师兄：装信正合适。上回就是信袋太薄，差点湿了。"},{"id":"fang-returnText","name":"方迟","field":"returnText","sourceText":"随信附一份普通药材：“我用不完，留给你备着。”","text":"随信附一份普通药材：“我用不完，留给你备着。”"},{"id":"dou-letter","name":"卢小豆","field":"letter","sourceText":"小豆回信：我是师兄，回什么信！……好吧，收到了。将军今天又追我了。","text":"小豆回信：我是师兄，回什么信！……好吧，收到了。将军今天又追我了。"},{"id":"dou-repeat","name":"卢小豆","field":"repeat","sourceText":"小豆：又给我？……那我就勉为其难收下了。","text":"小豆：又给我？……那我就勉为其难收下了。"},{"id":"dou-gift-food","name":"卢小豆","field":"gifts","gift":"food","sourceText":"小豆：吃的！你果然是好师弟！……这个我藏起来，不给将军看见。","text":"小豆：吃的！你果然是好师弟！……这个我藏起来，不给将军看见。"},{"id":"dou-gift-herb","name":"卢小豆","field":"gifts","gift":"herb","sourceText":"小豆：药？我又没受伤！……那我拿去喂将军试试。——开玩笑的，我交给叶蘅姐姐。","text":"小豆：药？我又没受伤！……那我拿去喂将军试试。——开玩笑的，我交给叶蘅姐姐。"},{"id":"dou-gift-pouch","name":"卢小豆","field":"gifts","gift":"pouch","sourceText":"小豆：布包？装弹弓的石子正好！你别告诉师母。","text":"小豆：布包？装弹弓的石子正好！你别告诉师母。"},{"id":"dou-returnText","name":"卢小豆","field":"returnText","sourceText":"随信塞来一把炒豆子：“分你一半，别说我小气。”","text":"小豆捎来一份院里收的豆子，可作普通食材：“师母说晒干了才能炒。炒好了，记得分我一半。”"},{"id":"man-letter","name":"周小满","field":"letter","sourceText":"小满回信：萧白哥的字没有我好看！但是我认得全。娘说让你回来吃饭。","text":"小满回信：萧白哥的字没有我好看！但是我认得全。娘说让你回来吃饭。"},{"id":"man-repeat","name":"周小满","field":"repeat","sourceText":"小满：又送我呀？我都装不下啦！","text":"小满：又送我呀？我都装不下啦！"},{"id":"man-gift-food","name":"周小满","field":"gifts","gift":"food","sourceText":"小满：好吃！我分给将军一口，就一口。","text":"小满：好吃！我分给将军一口，就一口。"},{"id":"man-gift-herb","name":"周小满","field":"gifts","gift":"herb","sourceText":"小满：这个我认得！是……是紫苏！不对？那我去问叶蘅姐姐。","text":"小满：这个我认得！是……是紫苏！不对？那我去问叶蘅姐姐。"},{"id":"man-gift-pouch","name":"周小满","field":"gifts","gift":"pouch","sourceText":"小满：好看的布包！我要装我认对了的叶子！","text":"小满：好看的布包！我要装我认对了的叶子！"},{"id":"man-returnText","name":"周小满","field":"returnText","sourceText":"随信夹着一片压干的叶子：“这是我认对的，送你。”","text":"小满另扎了一份药圃的普通药材，叶蘅替她写好了药名：“这回我真的认对了！”"}],"ui":{"arrival":"既入了门，就安心住下。\n明早来练场。鞋带绑紧些，别又踩着。","offer":"剑法跟我练。拳法先请你二师叔带着拆。你想从哪样学起？","offer-choice":"师父，我先学……","delivery-trained":"你跟我走前头。昨晚有雨，靠山这边还干些。药包别挡着眼睛。","delivery-untrained":"来，把这包轻的拿上。前头有段滑坡，到那儿叫我，咱们换着背。","delivery-choice":"陆大哥，前面那段……","apprenticeship-1":"次日清晨，萧白在院中找到周砚。","apprenticeship-2":"周先生，我想留下学武。再碰上栖河那样的事，心里才有点底。","apprenticeship-3":"能教。可不是今日学、明日就能下山逞本事。日日来练场，你坐得住么？","apprenticeship-4":"坐得住。……站也站得住。请您收我为徒。","apprenticeship-5":"好，先叫声师父。明早换双厚些的鞋，练场的碎石硌脚。","apprenticeship-6":"周先生，我想先借住些日子。去看看药圃，也给陈伯写封信。","apprenticeship-7":"房间给你留着。拜师的事不用急，忙完来吃早饭。"},"apprenticeship":[["","次日清晨，萧白在院中找到周砚。"],["萧白","周先生，我想留下学武。再碰上栖河那样的事，心里才有点底。"],["周砚","能教。可不是今日学、明日就能下山逞本事。日日来练场，你坐得住么？"],["萧白","坐得住。……站也站得住。请您收我为徒。"],["周砚","好，先叫声师父。明早换双厚些的鞋，练场的碎石硌脚。"],["叶蘅","周先生，我想先借住些日子。去看看药圃，也给陈伯写封信。"],["周砚","房间给你留着。拜师的事不用急，忙完来吃早饭。"]]};
function apply(id,x){const m=D.changes[id]||{},lines=ls=>ls.map(l=>({...l,text:m[l.text]??l.text}));return {...x,intro:lines(x.intro),closing:lines(x.closing),choices:x.choices.map(c=>({...c,lines:lines(c.lines)}))};}
function activities(data){for(const a of data.actions)if(D.activities[a.id])Object.assign(a,D.activities[a.id]);}
function relations(r){for(const l of D.correspondence){const p=r.profiles[l.name];if(!p)throw Error('Missing dialogue profile '+l.name);if(l.field==='gifts')p.gifts[l.gift]=l.text;else p[l.field]=l.text;}}
const api={...D,apply,activities,relations};if(typeof module==='object'&&module.exports)module.exports=api;else root.CultivationDialogue=api;
})(typeof globalThis!=='undefined'?globalThis:this);
